solutions.naive:
class Solution:
    def minGroups(self, intervals: list[list[int]]) -> int:
        points = set()
        for start, end in intervals:
            points.add(start)
            points.add(end)
        answer = 0
        for point in points:
            active = 0
            for start, end in intervals:
                if start <= point <= end:
                    active += 1
            answer = max(answer, active)
        return answer

solutions.better:
class Solution:
    def minGroups(self, intervals: list[list[int]]) -> int:
        events = []
        for start, end in intervals:
            events.append((start, 1))
            events.append((end + 1, -1))
        events.sort()
        active = 0
        answer = 0
        for _, delta in events:
            active += delta
            answer = max(answer, active)
        return answer

