class Solution:
    def minGroups(self, intervals: list[list[int]]) -> int:
        import heapq
        intervals.sort()
        heap = []
        answer = 0
        for start, end in intervals:
            while heap and heap[0] < start:
                heapq.heappop(heap)
            heapq.heappush(heap, end)
            answer = max(answer, len(heap))
        return answer

